float SLAMPipeline::evaluateGaussianOptimizationLoss(SLAMGaussianModel &model,
                                                     const std::vector<Camera> &cams,
                                                     const std::vector<TensorDict> &raycasts,
                                                     int max_cameras)
{
    if (model.getGaussianNum() <= 0 || cams.empty() || raycasts.empty() || cams.size() != raycasts.size())
        return std::numeric_limits<float>::infinity();

    const int sample_count =
        max_cameras > 0 ? std::min<int>(max_cameras, cams.size()) : int(cams.size());
    if (sample_count <= 0)
        return std::numeric_limits<float>::infinity();

    std::vector<int> indices = selectTemporalSpreadIndices(int(cams.size()), sample_count);
    if (indices.empty())
        return std::numeric_limits<float>::infinity();

    torch::NoGradGuard no_grad;
    model.setParamsDevice(model.device);
    model.updateSH(-1);

    double total_loss = 0.0;
    int valid_losses = 0;
    for (int idx : indices)
    {
        if (idx < 0 || idx >= int(cams.size()) || idx >= int(raycasts.size()))
            continue;
        const auto depth_it = raycasts[idx].find("depth_map");
        const auto color_it = raycasts[idx].find("color_map");
        if (depth_it == raycasts[idx].end() || color_it == raycasts[idx].end())
            continue;
        if (!depth_it->second.defined() || !color_it->second.defined())
            continue;

        Camera eval_cam = cams[idx];
        if (!eval_cam.image.defined())
            continue;
        eval_cam.toGPU();

        TensorDict render_res = model.forward(eval_cam, depth_it->second, color_it->second);
        if (render_res.find("rgb") == render_res.end() ||
            render_res.find("depth") == render_res.end() ||
            render_res.find("alpha") == render_res.end())
            continue;
        TensorDict loss = model.computeLoss(render_res, eval_cam, weight_configs);
        const auto total_it = loss.find("total");
        if (total_it == loss.end() || !total_it->second.defined())
            continue;
        const float loss_value = total_it->second.item<float>();
        if (!std::isfinite(loss_value))
            continue;
        total_loss += loss_value;
        ++valid_losses;
    }

    if (valid_losses == 0)
        return std::numeric_limits<float>::infinity();
    return static_cast<float>(total_loss / double(valid_losses));
}

float SLAMPipeline::evaluateGaussianReadinessDelta(SLAMGaussianModel &model,
                                                   const std::vector<Camera> &cams,
                                                   const std::vector<TensorDict> &raycasts,
                                                   int max_cameras,
                                                   float *sdf_l1_out,
                                                   float *hybrid_l1_out,
                                                   int *valid_count_out)
{
    if (sdf_l1_out != nullptr)
        *sdf_l1_out = std::numeric_limits<float>::quiet_NaN();
    if (hybrid_l1_out != nullptr)
        *hybrid_l1_out = std::numeric_limits<float>::quiet_NaN();
    if (valid_count_out != nullptr)
        *valid_count_out = 0;
    if (model.getGaussianNum() <= 0 || cams.empty() || raycasts.empty() || cams.size() != raycasts.size())
        return std::numeric_limits<float>::quiet_NaN();

    const int sample_count =
        max_cameras > 0 ? std::min<int>(max_cameras, cams.size()) : int(cams.size());
    if (sample_count <= 0)
        return std::numeric_limits<float>::quiet_NaN();

    std::vector<int> indices = selectTemporalSpreadIndices(int(cams.size()), sample_count);
    if (indices.empty())
        return std::numeric_limits<float>::quiet_NaN();

    torch::NoGradGuard no_grad;
    model.setParamsDevice(model.device);
    model.updateSH(-1);

    double sdf_l1_total = 0.0;
    double hybrid_l1_total = 0.0;
    int valid = 0;
    for (int idx : indices)
    {
        if (idx < 0 || idx >= int(cams.size()) || idx >= int(raycasts.size()))
            continue;
        const auto depth_it = raycasts[idx].find("depth_map");
        const auto color_it = raycasts[idx].find("color_map");
        if (depth_it == raycasts[idx].end() || color_it == raycasts[idx].end())
            continue;
        if (!depth_it->second.defined() || !color_it->second.defined())
            continue;

        Camera eval_cam = cams[idx];
        if (!eval_cam.image.defined())
            continue;
        eval_cam.toGPU();
        TensorDict render_res = model.forward(eval_cam, depth_it->second, color_it->second);
        if (render_res.find("rgb") == render_res.end() || !render_res["rgb"].defined())
            continue;
        const torch::Tensor gt_rgb = eval_cam.image.to(model.device);
        const float sdf_l1 = torch::mean(torch::abs(color_it->second.to(model.device) - gt_rgb)).item<float>();
        const float hybrid_l1 = torch::mean(torch::abs(torch::clamp(render_res["rgb"], 0, 1) - gt_rgb)).item<float>();
        if (!std::isfinite(sdf_l1) || !std::isfinite(hybrid_l1))
            continue;
        sdf_l1_total += sdf_l1;
        hybrid_l1_total += hybrid_l1;
        ++valid;
    }

    if (valid == 0)
        return std::numeric_limits<float>::quiet_NaN();
    const float sdf_l1 = float(sdf_l1_total / double(valid));
    const float hybrid_l1 = float(hybrid_l1_total / double(valid));
    if (sdf_l1_out != nullptr)
        *sdf_l1_out = sdf_l1;
    if (hybrid_l1_out != nullptr)
        *hybrid_l1_out = hybrid_l1;
    if (valid_count_out != nullptr)
        *valid_count_out = valid;
    return sdf_l1 - hybrid_l1;
}

int SLAMPipeline::gaussianSubmapBudgetCap(const GaussianSubmap &submap, int sdf_blocks) const
{
    if (submap_gaussian_budget_policy == "fixed")
        return submap_max_gaussians;
    if (submap_gaussian_budget_policy != "sdf_block_density")
        return submap_max_gaussians;

    int blocks = sdf_blocks;
    if (blocks < 0 && tsdf_engine != nullptr && submap.sdf_submap_id >= 0)
        blocks = tsdf_engine->getSubmapBlockCount(submap.sdf_submap_id);
    blocks = std::max(0, blocks);
    const int min_cap = std::max(0, submap_gaussian_budget_min);
    const int max_cap = std::max(min_cap, submap_gaussian_budget_max);
    const int base_cap = std::max(0, submap_gaussian_budget_base);
    const int density_cap =
        int(std::lround(float(base_cap) + std::max(0.0f, submap_gaussian_budget_blocks_density) * float(blocks)));
    return std::clamp(density_cap, min_cap, max_cap);
}

